obfuscateLink opts attr (TL.toStrict . renderHtml -> txt) s = do html5 <- gets stHtml5 let meth = writerEmailObfuscation opts let s' = T.toLower (T.take 7 s) <> T.drop 7 s case parseMailto s' of (Just (name', domain)) -> let domain' = T.replace "." " dot " domain at' = obfuscateChar '@' (linkText, altText) = if txt == T.drop 7 s' -- autolink then ("e", name' <> " at " <> domain') else ("'" <> obfuscateString txt <> "'", txt <> " (" <> name' <> " at " <> domain' <> ")") (_, classNames, _) = attr classNamesStr = T.concat $ map (" "<>) classNames in case meth of ReferenceObfuscation -> -- need to use preEscapedString or &'s are escaped to &amp; in URL return $ preEscapedText $ "<a href="" <> obfuscateString s' <> "" class="email">" <> obfuscateString txt <> "</a>" JavascriptObfuscation -> return $ (H.script ! A.type_ "text/javascript" $ preEscapedText ("
<!--
h='" <> obfuscateString domain <> "';a='" <> at' <> "';n='" <> obfuscateString name' <> "';e=n+a+h;
" <> "document.write('<a h'+'ref'+'="ma'+'ilto'+':'+e+'" clas'+'s="em' + 'ail" <> classNamesStr <> "">'+" <> linkText <> "+'<\/'+'a'+'>');
// -->
")) >> H.noscript (preEscapedText $ obfuscateString altText) _ -> throwError $ PandocSomeError $ "Unknown obfuscation method

